  { id: "close", name: N_("膝上跟拍"), desc: N_("相机跟随，脸约是全身的 2 倍，眼睛更稳"), size: "46%", align: "flex-start" },
  { id: "full", name: N_("全身固定"), desc: N_("整个人在画面里，动作完整"), size: "22%", align: "center" }
