  const pendA = made.filter(([, a]) => a.review === "pending").length;
  const run = running || null;
  const steps = [];
  steps.push(
    story ? { key: "script", state: "done", note: t("{n} 段", { n: total }) } : { key: "script", state: "you", note: t("导演在写，写完你读一遍") }
  );
