  steps.push(
    run === "assets" ? { key: "assets", state: "run", note: t("正在拍") } : aDone ? { key: "assets", state: "done", note: t("{n} 张都通过", { n: assets.length }) } : pendA ? { key: "assets", state: "you", note: t("等你审 {n} 张", { n: pendA }) } : { key: "assets", state: "next", note: t("{a} / {b} 张通过", { a: passA, b: assets.length }) }
  );
